module slime_combiner (\n    input wire [16:0] n,\n    output reg [7:0] values [0:16],\n    output reg [4:0] count\n);\n\ninteger i;\nreg [4:0] idx;\n\nalways @(*) begin\n    // Initialize all values to 0\n    for (i = 0; i < 17; i = i + 1) begin\n        values[i] = 8'd0;\n    end\n    \n    idx = 0;\n    // Process bits from high to low\n    for (i = 16; i >= 0; i = i - 1) begin\n        if (n[i]) begin\n            values[idx] = i + 8'd1;\n            idx = idx + 5'd1;\n        end\n    end\n    count = idx;\nend\n\nendmodule